    int n; if (!(cin >> n)) return 0;
    vector<int> nums(n);
    for (int i = 0; i < n; i++) cin >> nums[i];
    int target; cin >> target;
    unordered_map<int, int> mp;
    for (int i = 0; i < n; i++) {
        int comp = target - nums[i];
        if (mp.count(comp)) {
            cout << mp[comp] << " " << i << "\n";
            return 0;
        }
        mp[nums[i]] = i;
    }
    return 0;
}

